#include "streamforge/benchmark/benchmark.hpp"
#include <algorithm>
#include <stdexcept>
namespace streamforge::benchmark {
double percentile(std::vector<double> samples, double fraction) { if (samples.empty() || fraction < 0 || fraction > 1) throw std::invalid_argument("invalid percentile samples or fraction"); std::sort(samples.begin(), samples.end()); return samples[static_cast<std::size_t>(fraction*static_cast<double>(samples.size()-1))]; }
Summary summarize(std::vector<double> samples) { return {percentile(samples,.50),percentile(samples,.95),percentile(samples,.99)}; }
Options parse_options(int argc, char** argv) { if(argc<2) throw std::invalid_argument("missing data directory"); Options o; o.data_directory=argv[1]; for(int i=2;i<argc;i+=2) { if(i+1>=argc) throw std::invalid_argument("each option needs a value"); const std::string key=argv[i], value=argv[i+1]; auto number=[&]{const auto n=std::stoull(value);if(n==0)throw std::invalid_argument("numeric options must be positive");return static_cast<std::size_t>(n);}; if(key=="--messages")o.messages=number(); else if(key=="--payload-bytes")o.payload_bytes=number(); else if(key=="--batch-size")o.batch_size=number(); else if(key=="--warmup-batches")o.warmup_batches=number(); else if(key=="--repetitions")o.repetitions=number(); else if(key=="--clients")o.clients=number(); else if(key=="--partitions")o.partitions=number(); else if(key=="--profile"){if(value!="on"&&value!="off")throw std::invalid_argument("profile must be on or off");o.profile=value=="on";} else if(key=="--mode"){if(value!="appended"&&value!="synced")throw std::invalid_argument("mode must be appended or synced");o.mode=value;}else throw std::invalid_argument("unknown option: "+key);} if(o.batch_size>o.messages)throw std::invalid_argument("batch size cannot exceed messages");if(o.clients!=1&&o.clients!=2&&o.clients!=4&&o.clients!=8&&o.clients!=16)throw std::invalid_argument("clients must be one of 1, 2, 4, 8, or 16");if(o.partitions!=1&&o.partitions!=4)throw std::invalid_argument("partitions must be 1 or 4");return o;}
std::uint32_t target_partition(std::size_t client_index, std::size_t partitions) { if (partitions == 0) throw std::invalid_argument("partitions must be positive"); return static_cast<std::uint32_t>(client_index % partitions); }
std::vector<std::size_t> messages_per_partition(std::size_t messages, std::size_t clients, std::size_t partitions) { if (clients == 0 || partitions == 0) throw std::invalid_argument("clients and partitions must be positive"); std::vector<std::size_t> counts(partitions); for (std::size_t client = 0; client < clients; ++client) { counts[target_partition(client, partitions)] += messages / clients + (client < messages % clients ? 1U : 0U); } return counts; }
}
